function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is a whole number from 1 to nums.length.';
  for (let i = 0; i < nums.length; i++) {
    if (!Number.isInteger(nums[i]) || nums[i] < 1 || nums[i] > 100000) return 'Each value is a whole number from 1 to 100000.';
    if (i > 0 && nums[i] < nums[i - 1]) return 'nums must be sorted in non-decreasing order.';
  }
  return null;
}

