function canDivideIntoSubsequences(nums, k) {
  let maxFreq = 0;
  let run = 0;

  for (let i = 0; i < nums.length; i++) {
    if (i > 0 && nums[i] === nums[i - 1]) {
      run++;
    } else {
      run = 1;
    }
    maxFreq = Math.max(maxFreq, run);
  }

  return maxFreq * k <= nums.length;
}

