function canDivideIntoSubsequences(nums, k) {
  // Try every way to deal the sorted values into strictly increasing groups.
  const groups = [];
  const place = (i) => {
    let missing = 0;
    for (const g of groups) missing += Math.max(0, k - g.length);
    if (missing > nums.length - i) return false;
    if (i === nums.length) return true;
    for (const g of groups) {
      if (g[g.length - 1] < nums[i]) {
        g.push(nums[i]);
        const ok = place(i + 1);
        g.pop();
        if (ok) return true;
      }
    }
    groups.push([nums[i]]);
    const ok = place(i + 1);
    groups.pop();
    return ok;
  };
  return place(0);
}

