function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const n = size === 'large' ? 1500 + pick(501) : 1 + pick(9);
  const ranges = size === 'large' ? [1, 5, 60, 800, 100000] : [1, 2, 3, 5, 8];
  const top = ranges[pick(ranges.length)];
  const nums = Array.from({ length: n }, () => 1 + pick(top)).sort((a, b) => a - b);
  let maxFreq = 0;
  for (let i = 0, j = 0; i < n; i = j) {
    while (j < n && nums[j] === nums[i]) j++;
    maxFreq = Math.max(maxFreq, j - i);
  }
  // Aim k at the boundary floor(n / maxFreq) so that both answers appear.
  const limit = Math.floor(n / maxFreq);
  let k = rand() < 0.2 ? 1 + pick(n) : limit + (rand() < 0.5 ? 0 : 1) - (rand() < 0.2 ? 1 : 0);
  k = Math.min(n, Math.max(1, k));
  return [nums, k];
}
